#!/usr/bin/env python3
"""Persistent driver: keeps tmux session alive between bash calls.
Usage: drv_entdlg.py SESS KEYS...
  If SESS not existing, creates it (with --cols/--rows via env COLS/ROWS, HOME via env TJHOME, args via TJARGS).
Special: @cap @capE @sN.N  @new (force new session)
"""
import os, subprocess, sys, time, shutil

EXE = "/workspace/executable"

def sh(*a):
    return subprocess.run(a, capture_output=True, text=True)

def exists(sess):
    return sh("tmux", "has-session", "-t", sess).returncode == 0

def main():
    args = sys.argv[1:]
    sess = args[0]
    keys = args[1:]
    home = os.environ.get("TJHOME", f"/tmp/tjhome_{sess}")
    cols = os.environ.get("COLS", "120")
    rows = os.environ.get("ROWS", "40")
    xargs = os.environ.get("TJARGS", "")
    force = "@new" in keys
    if force:
        keys = [k for k in keys if k != "@new"]
    if force or not exists(sess):
        sh("tmux", "kill-session", "-t", sess)
        if os.environ.get("FRESHHOME", "1") == "1" and os.path.isdir(home):
            shutil.rmtree(home)
        os.makedirs(home, exist_ok=True)
        cmd = f"env HOME={home!r} TERM=xterm-256color {EXE} {xargs}; echo __TJEXIT_$?__; sleep 3000"
        sh("tmux", "new-session", "-d", "-s", sess, "-x", cols, "-y", rows, cmd)
        time.sleep(1.0)
    n = 0
    for k in keys:
        if k in ("@cap", "@capE"):
            n += 1
            a = ["tmux", "capture-pane", "-p", "-t", sess]
            if k == "@capE":
                a.insert(2, "-e")
            print(f"===== CAP {n} =====")
            print(sh(*a).stdout.rstrip("\n"))
            print(f"===== /CAP {n} =====")
        elif k.startswith("@s"):
            time.sleep(float(k[2:]))
        elif k.startswith("^"):
            sh("tmux", "send-keys", "-t", sess, k[1:]); time.sleep(0.25)
        else:
            sh("tmux", "send-keys", "-t", sess, "-l", k); time.sleep(0.25)

if __name__ == "__main__":
    main()
